import {readPlayer,writePlayer,backup,parseBackup,WORLD_NAMES,WORLD_ROUTES} from './shared/saves.js';
const $=id=>document.getElementById(id),NAMES={ari:'EMBERIA • Volcano Quest',kal:'LUMINARA • Star Quest'};
const storage=(()=>{try{return localStorage;}catch{return {getItem:()=>null,setItem(){throw Error('Saving is unavailable in this browser session.');}};}})();
const LEGACY_ORIGIN='https://star-quest-kal-sky-adventure.khisanthax.chatgpt.site';
let active=null,serial=Promise.resolve(),migrationWindow=null,pendingImport=null,readyTimer=null,disposedCount=0;
function notify(text){$('notice').textContent=text;}
function refresh(){for(const player of ['ari','kal']){const p=readPlayer(storage,player);$(player+'-status').textContent=p?.run?`Continue chapter ${p.run.level+1} • progress saved`:p?.lastResult?'Adventure completed • ready to play again':player==='ari'?'13 Earth Science words':'Sky science with Beep';}$('transfer-kal').hidden=!!readPlayer(storage,'kal');}
async function closeGame(){if(!active)return;const item=active;active=null;clearTimeout(readyTimer);try{await Promise.race([item.frame.contentWindow.arcadeLifecycle?.dispose(),new Promise(resolve=>setTimeout(resolve,1200))]);}catch{}item.frame.remove();disposedCount++;$('game-slot').replaceChildren();$('loading').hidden=true;}
async function navigate(player){await closeGame();if(!NAMES[player]){$('adventure').hidden=true;$('picker').hidden=false;refresh();$('choose-ari').focus({preventScroll:true});return;}$('picker').hidden=true;$('adventure').hidden=false;$('active-player').textContent=NAMES[player];$('loading').hidden=false;const frame=document.createElement('iframe');frame.id='adventure-frame';frame.title=NAMES[player];frame.setAttribute('allow','autoplay');frame.src=`./${player}/index.html`;active={player,frame};$('game-slot').append(frame);frame.addEventListener('load',()=>{if(active?.frame===frame){$('loading').hidden=true;frame.contentWindow.focus();}},{once:true});readyTimer=setTimeout(()=>{if(active?.frame===frame){$('loading').textContent='Still loading. You can return to the arcade and try again.';}},8000);}
function route(){const raw=location.hash.slice(1),key=Object.keys(WORLD_ROUTES).find(p=>WORLD_ROUTES[p]===raw)||(NAMES[raw]?raw:null);if(key&&raw!==WORLD_ROUTES[key])history.replaceState(null,'','#'+WORLD_ROUTES[key]);serial=serial.then(()=>navigate(NAMES[key]?key:null)).catch(()=>{notify('Please choose your world again.');$('picker').hidden=false;$('adventure').hidden=true;});return serial;}
function go(player){const routeName=WORLD_ROUTES[player]||'';if(location.hash===`#${routeName}`)route();else location.hash=routeName;}
for(const player of ['ari','kal'])$( `choose-${player}`).addEventListener('click',()=>go(player));
$('back-arcade').addEventListener('click',()=>go(null));window.addEventListener('hashchange',route);window.addEventListener('pageshow',e=>{if(e.persisted)route();});
window.addEventListener('message',e=>{
 if(e.origin===location.origin&&e.source===active?.frame.contentWindow){if(e.data?.type==='arcade:home')go(null);if(e.data?.type==='arcade:ready'){clearTimeout(readyTimer);$('loading').hidden=true;}}
 if(e.origin===LEGACY_ORIGIN&&e.source===migrationWindow&&e.data?.type==='science-arcade:legacy-save'&&e.data.player==='kal'){
  if(!e.data.progress){$('save-message').textContent='No saved Star Quest progress was found in that browser window.';return;}
  try{stageImport({format:'science-adventure-arcade-save-v1',player:'kal',progress:e.data.progress});$('save-tools').showModal();migrationWindow?.postMessage({type:'science-arcade:received'},LEGACY_ORIGIN);}catch(err){$('save-message').textContent=err.message;}
 }
});
function download(player){try{const data=backup(player,readPlayer(storage,player));const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`science-arcade-${WORLD_ROUTES[player]}-save.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);$('save-message').textContent=`${WORLD_NAMES[player]} backup is ready.`;}catch(e){$('save-message').textContent=e.message;}}
function openTools(){pendingImport=null;$('import-confirm').hidden=true;$('save-message').textContent='';$('save-tools').showModal();}
function stageImport(data){const checked=parseBackup(JSON.stringify(data));pendingImport=checked;$('import-label').textContent=`Import ${WORLD_NAMES[checked.player]}’s progress? ${readPlayer(storage,checked.player)?'This replaces only that player’s current arcade save.':'The other player’s save will stay unchanged.'}`;$('import-confirm').hidden=false;$('save-message').textContent='Check the world name before importing.';}
$('saves-button').addEventListener('click',openTools);$('close-tools').addEventListener('click',()=>$('save-tools').close());
for(const player of ['ari','kal'])$('export-'+player).addEventListener('click',()=>download(player));
$('import-backup').addEventListener('click',()=>$('backup-file').click());$('backup-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>500000)throw Error('That backup is too large.');stageImport(parseBackup(await f.text()));}catch(err){$('save-message').textContent=err.message;}e.target.value='';});
$('confirm-import').addEventListener('click',async()=>{if(!pendingImport)return;const data=pendingImport;await serial;await closeGame();if(pendingImport!==data)return;$('adventure').hidden=true;$('picker').hidden=false;location.hash='';try{writePlayer(storage,pendingImport.player,pendingImport.progress);$('save-message').textContent=`${WORLD_NAMES[pendingImport.player]}’s progress imported. The other save is unchanged.`;$('import-confirm').hidden=true;pendingImport=null;refresh();}catch(e){$('save-message').textContent=e.message;}});
$('cancel-import').addEventListener('click',()=>{pendingImport=null;$('import-confirm').hidden=true;$('save-message').textContent='Import canceled. Both saves are unchanged.';});
function transferKal(){if(!$('save-tools').open)openTools();migrationWindow=window.open(LEGACY_ORIGIN+'/arcade-transfer.html','science-arcade-save-transfer','popup,width=650,height=550');$('save-message').textContent=migrationWindow?'In the Star Quest window, tap Transfer Star Quest Save. Then return here to confirm.':'The browser blocked the transfer window. Allow this pop-up and try again, or import a downloaded backup.';}
$('transfer-kal').addEventListener('click',transferKal);$('transfer-popup').addEventListener('click',transferKal);
window.addEventListener('pagehide',()=>{try{active?.frame.contentWindow.arcadeLifecycle?.dispose();}catch{}});
Object.defineProperty(window,'scienceArcade',{get:()=>({active:active?.player||null,frames:document.querySelectorAll('iframe').length,disposedCount})});
refresh();route();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
